<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { Report, ReportVersion, SceneSpec } from '../types'
import { ApiError, downloadVersion, getReport, getSource, getVersion, getWorkflow, listVersions, reportAction, requireReport, saveVersion } from '../services/research'
import WorkflowVisual from './WorkflowVisual.vue'
import SceneViewer from './SceneViewer.vue'
const props=defineProps<{ report:Report; readonly?:boolean }>()
const emit=defineEmits<{ saved:[report:Report] }>()
const tab=ref('A'),busy=ref(''),error=ref(''),notice=ref('')
const draft=ref<Report>(JSON.parse(JSON.stringify(props.report)))
const workflow=computed(()=>draft.value.workflow??{})
const versions=ref<ReportVersion[]>([]),selectedVersion=ref(props.report.version??1),previous=ref<Report>()
const sourceDetail=ref(''),evidenceFilter=ref(''),jsonEditor=ref('')
const actionResults=ref<Record<string,unknown>>({})
const reviews=ref<Record<string,unknown>[]>([])
const operation=ref<'sum'|'mean'|'min'|'max'|'difference'|'ratio'|'percent_change'>('sum')
const inputRefs=ref<string[]>([])
const calculationRows=computed(()=>(workflow.value.datasets??[]).flatMap(dataset=>(dataset.rows??[]).flatMap((row,index)=>Number.isFinite(row.value)?[{ref:row.id||`${dataset.id}:${index}`,label:`${dataset.metric||dataset.id} · ${row.label}`,value:row.value,unit:dataset.unit??''}]:[])))
const selectedInputs=computed(()=>inputRefs.value.map(id=>calculationRows.value.find(row=>row.ref===id)).filter(row=>!!row))
const requiresPair=computed(()=>['difference','ratio','percent_change'].includes(operation.value))
const canCalculate=computed(()=>!props.readonly&&!busy.value&&!dirty.value&&(requiresPair.value?selectedInputs.value.length===2:selectedInputs.value.length>0))
const operationHint=computed(()=>({sum:'求和',mean:'算术平均值',min:'最小值',max:'最大值',difference:'第二项 − 第一项',ratio:'第一项 ÷ 第二项',percent_change:'(第二项 − 第一项) ÷ |第一项| × 100%'}[operation.value]))
const automaticReview=computed(()=>{const value=workflow.value.quality_review as Record<string,unknown>|undefined;return value?.kind==='automatic'?value:undefined})
const reviewVersion=(value:unknown)=>{const review=value as Record<string,unknown>|null;const number=review?.report_version??review?.version;return typeof number==='number'?number:undefined}
const humanReviews=computed(()=>reviews.value.filter(r=>r.kind==='human'&&reviewVersion(r)===(props.report.version??1)))
const aiReviews=computed(()=>reviews.value.filter(r=>r.kind==='ai'&&reviewVersion(r)===(props.report.version??1)))
const aiReview=computed(()=>{
  if(actionResults.value.review)return actionResults.value.review
  if(aiReviews.value.length)return aiReviews.value
  if(workflow.value.ai_quality_review)return workflow.value.ai_quality_review
  const review=workflow.value.quality_review as Record<string,unknown>|undefined
  return review?.kind==='automatic'?'尚未运行本版本的独立 AI 审查。':review
})
const aiReviewNotice=computed(()=>{
  const value=aiReview.value
  if(!value||typeof value==='string')return '当前版本尚无绑定的 AI 审查结果。'
  const version=reviewVersion(Array.isArray(value)?value[0]:value),current=props.report.version??1
  if(version===undefined)return '此审查未记录报告版本，不能视为当前版本已审查。'
  return version===current?`此 AI 审查对应报告 v${version}；审查记录不等同人工事实验收。`:`这是 v${version} 的历史 AI 审查；当前 v${current} 尚需重新审查。`
})
const humanReview=computed(()=>{
  const actionReview=actionResults.value['human-review']
  if(actionReview)return reviewVersion(actionReview)===(props.report.version??1)?actionReview:{notice:'此操作返回的是其他版本的人工审查，不代表当前版本已审查。',record:actionReview}
  if(humanReviews.value.length)return humanReviews.value
  const old=workflow.value.human_review
  if(!old)return `报告 v${props.report.version??1} 尚无人工审查记录。`
  return reviewVersion(old)===(props.report.version??1)?old:{notice:'此为历史或未绑定版本的人工审查，不代表当前版本已审查。',record:old}
})
const reviewer=ref(''),reviewNotes=ref(''),decision=ref('approved')
const shareToken=ref(''),shareUrl=ref(''),shareExpiry=ref('')
const dirty=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(props.report))
const evidence=computed(()=>(workflow.value.evidence??[]).filter(e=>`${e.id} ${e.quote} ${e.source_id}`.toLowerCase().includes(evidenceFilter.value.toLowerCase())))
const changes=computed(()=>{
  if(!previous.value)return []
  const result:string[]=[],old=previous.value,current=props.report
  if(old.title!==current.title)result.push(`标题：${old.title} → ${current.title}`)
  const ids=new Set([...old.chapters.map(c=>c.id),...current.chapters.map(c=>c.id)])
  ids.forEach(id=>{const a=old.chapters.find(c=>c.id===id),b=current.chapters.find(c=>c.id===id);if(!a)result.push(`新增章节：${b?.title}`);else if(!b)result.push(`移除章节：${a.title}`);else if(JSON.stringify(a)!==JSON.stringify(b))result.push(`修改章节：${b.title}`)})
  if(JSON.stringify(old.workflow?.scene)!==JSON.stringify(current.workflow?.scene))result.push('三维结构发生变化')
  if(JSON.stringify(old.workflow?.visuals)!==JSON.stringify(current.workflow?.visuals))result.push('图解结构发生变化')
  if(old.summary!==current.summary)result.push('摘要发生变化')
  return result
})
function jumpChapter(id:string){document.getElementById(`chapter-${id}`)?.scrollIntoView({behavior:'smooth'})}
const stringify=(value:unknown)=>typeof value==='string'?value:JSON.stringify(value,null,2)??'尚无记录'
watch(()=>props.report,(report,old)=>{if(old?.version!==report.version){actionResults.value={};reviews.value=[];inputRefs.value=[]}draft.value=JSON.parse(JSON.stringify(report));selectedVersion.value=report.version??1;jsonEditor.value=JSON.stringify(report.workflow,null,2);void refreshVersions();void refreshReviews()},{immediate:true})
async function run(name:string,action:()=>Promise<void>){if(busy.value)return;busy.value=name;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=''}}
async function refreshVersions(){if(props.readonly)return;try{versions.value=(await listVersions(props.report.id)).versions}catch(e){error.value=e instanceof Error?e.message:'版本记录暂不可用'}}
async function refreshReviews(){if(props.readonly)return;const version=props.report.version??1;try{const value=await getWorkflow(props.report.id,version);if(version===(props.report.version??1))reviews.value=Array.isArray(value.reviews)?value.reviews:[]}catch{if(version===(props.report.version??1))reviews.value=[]}}
async function save(){await run('save',async()=>{const saved=await saveVersion(props.report.id,props.report.version??1,draft.value);emit('saved',saved);notice.value=`已保存为 v${saved.version??1}，请重新检查本版本。`;await refreshVersions()})}
function toggleInput(id:string,checked:boolean){inputRefs.value=checked?[...new Set([...inputRefs.value,id])]:inputRefs.value.filter(value=>value!==id)}
function moveInput(index:number,offset:number){const next=[...inputRefs.value],target=index+offset;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target]!,next[index]!];inputRefs.value=next}
async function calculate(){if(!canCalculate.value)return;await run('calculate',async()=>{const result=await reportAction(props.report.id,'calculate',{base_version:props.report.version??1,operation:operation.value,input_refs:[...inputRefs.value]});const saved=requireReport(result.report);emit('saved',saved);notice.value=`核算完成，已保存为 v${saved.version??1}。新结果可在计算记录中查看。`;await refreshVersions()})}
async function loadPrevious(){await run('compare',async()=>{previous.value=await getVersion(props.report.id,selectedVersion.value)})}
async function restore(){await run('restore',async()=>{const saved=await reportAction(props.report.id,'restore',{version:selectedVersion.value,base_version:props.report.version??1});emit('saved',saved as unknown as Report);notice.value='已从历史版本创建新版本；已发布链接仍指向原版本。';await refreshVersions()})}
async function action(name:string){await run(name,async()=>{actionResults.value[name]=await reportAction(props.report.id,name,{version:props.report.version??1,...(name==='human-review'?{reviewer:reviewer.value,notes:reviewNotes.value,decision:decision.value}:{})});notice.value=name==='human-review'?'已记录人工审查。':'检查已完成，结果见下方。';const latest=await getReport(props.report.id);emit('saved',latest)})}
async function publish(){await run('publish',async()=>{const result=await reportAction(props.report.id,'publish',{version:selectedVersion.value,ttl_seconds:86400});shareToken.value=String(result.token??'');shareUrl.value=new URL(String(result.url??`/#/share/${shareToken.value}`),location.origin).href;shareExpiry.value=String(result.expiresAt??'');notice.value=`已冻结并分享 v${result.version??selectedVersion.value}；修改新版本不会改变此链接。`})}
async function revoke(){await run('revoke',async()=>{await reportAction(props.report.id,'revoke-share',{token:shareToken.value});notice.value='分享链接已撤销。';shareUrl.value='';shareToken.value=''})}
async function download(format:'zip'|'html'){await run('export',()=>downloadVersion(props.report.id,selectedVersion.value,format))}
async function inspectSource(id:string,chunkId?:string){await run('source',async()=>{
  const source=workflow.value.sources?.find(item=>item.id===id)
  if(!props.readonly){
    try{
      const original=await getSource(id),chunks=original.chunks??[]
      sourceDetail.value=stringify({access:'当前会话私有原件',title:original.title||original.name,chunks:chunkId?chunks.filter(chunk=>chunk.id===chunkId):chunks})
      tab.value='A';return
    }catch(cause){if(!(cause instanceof ApiError)||cause.status!==404)throw cause}
  }
  const quoted=source?.excerpts?.length?source.excerpts:(source?.chunks??[]).flatMap(chunk=>(chunk.quotes??[]).map(quote=>({...quote,chunk_id:chunk.id})))
  const excerpts=quoted.length?quoted.filter(item=>!chunkId||item.chunk_id===chunkId).map(({evidence_id,chunk_id,quote,locator,verification})=>({evidence_id,chunk_id,quote,locator,verification})):(workflow.value.evidence??[]).filter(item=>item.source_id===id&&(!chunkId||item.chunk_id===chunkId)).map(item=>({evidence_id:item.id,chunk_id:item.chunk_id,quote:item.quote,locator:item.locator}))
  const locations=(source?.chunks??[]).filter(chunk=>!chunkId||chunk.id===chunkId).map(({id,page,paragraph,start,end})=>({id,page,paragraph,start,end}))
  if(!source&&!excerpts.length)throw new Error('此来源暂未保留可查看的引用摘录。')
  sourceDetail.value=stringify({access:'报告引用摘录与定位，不包含完整原件',title:source?.title||source?.name,url:source?.url,chunk_locations:locations,quoted_excerpts:excerpts})
  tab.value='A'
})}
function updateScene(scene:SceneSpec){draft.value={...draft.value,workflow:{...workflow.value,scene}}}
function applyJson(){try{const value=JSON.parse(jsonEditor.value);if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('工作流必须是 JSON 对象。');draft.value={...draft.value,workflow:value};notice.value='结构已载入草稿，点击保存新版本后生效。';error.value=''}catch(e){error.value=e instanceof Error?e.message:'JSON 格式无效'}}
</script>
<template>
  <details class="report-workspace"><summary>研究工作区 · A–D <span class="tiny-badge">v{{ report.version??1 }}{{ readonly?' · 冻结分享':'' }}</span></summary>
    <div class="stage-tabs" role="tablist" aria-label="研究工作区阶段"><button v-for="item in [{id:'A',title:'目标与材料'},{id:'B',title:'研究与计算'},{id:'C',title:'阅读与图解'},{id:'D',title:'审查与交付'}]" :key="item.id" role="tab" :aria-selected="tab===item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{ item.id }} · {{ item.title }}</button></div>
    <p v-if="error" class="upload-error" role="alert">{{ error }}</p><p v-if="notice" class="workspace-notice" role="status">{{ notice }}</p><p v-if="busy" role="status" class="muted">正在处理…</p><div v-if="dirty&&!readonly" class="draft-notice">当前有未保存修改。<button class="text-button" :disabled="!!busy" @click="save">保存新版本</button></div>
    <section v-if="tab==='A'" role="tabpanel" aria-label="A 目标与材料"><h3>调研范围</h3><dl class="spec-grid"><dt>问题</dt><dd>{{ workflow.research_spec?.question||report.question }}</dd><dt>读者</dt><dd>{{ workflow.research_spec?.reader||'未指定' }}</dd><dt>范围</dt><dd>{{ workflow.research_spec?.scope||'未指定' }}</dd></dl><h3>来源材料</h3><div v-for="source in workflow.sources" :key="source.id" class="evidence-card"><strong>{{ source.title||source.name||source.id }}</strong><p class="muted">{{ source.kind }} · {{ source.id }}</p><a v-if="source.url&&/^https?:\/\//i.test(source.url)" :href="source.url" target="_blank" rel="noopener noreferrer" class="text-link">打开来源</a> <button class="text-button" :disabled="!!busy" @click="inspectSource(source.id)">查看来源片段</button></div><pre v-if="sourceDetail" class="record-preview">{{ sourceDetail }}</pre><h3>证据与原文定位</h3><input v-model="evidenceFilter" class="workspace-input" placeholder="搜索证据或来源编号" aria-label="搜索证据"/><div v-for="item in evidence" :key="item.id" class="evidence-card"><small>{{ item.id }} · {{ item.statement_kind||'未分类' }} · {{ item.verification?.quote_match?'摘录匹配':'待核实' }}</small><blockquote>{{ item.quote||'未保留摘录' }}</blockquote><p class="muted">{{ item.locator?.page?`第 ${item.locator.page} 页`:'' }} {{ item.locator?.paragraph?`第 ${item.locator.paragraph} 段`:'' }} {{ item.chunk_id }}</p><button v-if="item.source_id" class="text-button" :disabled="!!busy" @click="inspectSource(item.source_id,item.chunk_id)">定位原文</button></div><p v-if="!evidence.length" class="muted">没有匹配的证据记录；正文中的待核实说明仍需关注。</p></section>
    <section v-if="tab==='B'" role="tabpanel" aria-label="B 研究与计算"><h3>研究计划</h3><div v-for="(item,index) in workflow.plan?.subquestions" :key="item.id??index" class="evidence-card"><strong>{{ item.question }}</strong><p>{{ item.query }}</p><details v-if="item.actions?.length"><summary>检索与分析动作</summary><pre>{{ stringify(item.actions) }}</pre></details></div><details open><summary>研究 IR · 结论、冲突与缺口</summary><div v-for="(value,key) in workflow.research_ir" :key="key" class="evidence-card"><strong>{{ key }}</strong><pre>{{ stringify(value) }}</pre></div></details><h3>数据集</h3><div v-for="dataset in workflow.datasets" :key="dataset.id" class="evidence-card"><strong>{{ dataset.metric||dataset.id }} · {{ dataset.unit }} {{ dataset.period }}</strong><div class="table-scroll"><table><thead><tr><th>项目</th><th>数值</th><th>来源</th></tr></thead><tbody><tr v-for="(row,index) in dataset.rows" :key="index"><td>{{ row.label }}</td><td>{{ row.value }}</td><td>{{ row.source_id||'待核实' }}</td></tr></tbody></table></div></div><details v-if="!readonly" class="calculation-form" open><summary>主动核算 · 保存新版本</summary><p class="muted">按勾选顺序使用已有数据行，可调整输入顺序。运算仅使用固定数值工具。</p><label class="calculation-operation">运算<select v-model="operation" aria-label="核算运算"><option value="sum">求和 sum</option><option value="mean">平均值 mean</option><option value="min">最小值 min</option><option value="max">最大值 max</option><option value="difference">差值 difference</option><option value="ratio">比值 ratio</option><option value="percent_change">变化率 percent_change</option></select></label><p class="calculation-hint">{{ operationHint }}{{ requiresPair?' · 请按顺序选择恰好 2 行':' · 至少选择 1 行' }}</p><div class="calculation-inputs"><label v-for="row in calculationRows" :key="row.ref"><input type="checkbox" :checked="inputRefs.includes(row.ref)" :disabled="!!busy" :aria-label="`核算输入：${row.label}`" @change="toggleInput(row.ref,($event.target as HTMLInputElement).checked)"/><span>{{ row.label }}：{{ row.value }} {{ row.unit }}</span></label></div><ol v-if="selectedInputs.length" class="calculation-order" aria-label="核算输入顺序"><li v-for="(row,index) in selectedInputs" :key="row.ref"><span>第 {{ index+1 }} 项 · {{ row.label }}：{{ row.value }} {{ row.unit }}</span><button class="text-button" :disabled="index===0||!!busy" :aria-label="`上移输入 ${index+1}`" @click="moveInput(index,-1)">上移</button><button class="text-button" :disabled="index===selectedInputs.length-1||!!busy" :aria-label="`下移输入 ${index+1}`" @click="moveInput(index,1)">下移</button></li></ol><p v-if="!calculationRows.length" class="muted">本报告暂无可核算的有限数值数据行。</p><button class="primary-button" :disabled="!canCalculate" @click="calculate">计算并保存新版本</button><p v-if="dirty" class="muted">请先保存当前草稿，再进行核算。</p></details><h3>计算记录</h3><div v-for="calculation in workflow.calculations" :key="calculation.id" class="evidence-card"><strong>{{ calculation.operation }} · {{ calculation.status }}</strong><p>{{ calculation.formula }}</p><p>结果：{{ stringify(calculation.result) }} {{ calculation.unit }}</p><details><summary>输入与来源</summary><pre>{{ stringify({inputs:calculation.inputs,source_refs:calculation.source_refs}) }}</pre></details></div><p v-if="!workflow.calculations?.length" class="muted">本报告没有可展示的计算记录。</p></section>
    <section v-if="tab==='C'" role="tabpanel" aria-label="C 阅读与图解"><h3>阅读计划</h3><p>{{ workflow.reading_plan?.audience }} · {{ workflow.reading_plan?.goal }}</p><div v-for="item in workflow.reading_plan?.sections" :key="item.chapter_id" class="evidence-card"><a class="text-link" :href="`#chapter-${item.chapter_id}`" @click.prevent="jumpChapter(item.chapter_id)">{{ report.chapters.find(c=>c.id===item.chapter_id)?.title||item.chapter_id }}</a><p>{{ item.question }}</p><p>{{ item.goal }}</p><small>证据：{{ item.evidence_refs?.join('、')||'待关联' }}</small><details v-if="item.prerequisites"><summary>阅读前置知识</summary><pre>{{ stringify(item.prerequisites) }}</pre></details></div><details v-if="workflow.narrative_blocks?.length"><summary>语义内容块</summary><div v-for="block in workflow.narrative_blocks" :key="block.id" class="evidence-card"><small>{{ block.semantic_role }} · {{ block.chapter_id }}</small><p>{{ block.text }}</p><small>关联证据：{{ block.evidence_refs?.join('、') }}</small></div></details><WorkflowVisual v-for="visual in workflow.visuals" :key="visual.id" :visual="visual"/><SceneViewer v-if="workflow.scene" :scene="workflow.scene" :editable="!readonly" @change="updateScene"/><p v-else class="muted">本报告未生成三维结构，可在发起研究时启用概念三维。</p></section>
    <section v-if="tab==='D'" role="tabpanel" aria-label="D 审查与交付"><div class="review-grid"><details open><summary>程序一致性检查</summary><pre>{{ stringify(actionResults.validate??workflow.validation??automaticReview) }}</pre></details><details open><summary>AI 内容审查</summary><p class="muted ai-review-version">{{ aiReviewNotice }}</p><pre>{{ stringify(aiReview) }}</pre></details><details open><summary>人工审查（独立记录）</summary><p class="muted">当前报告 v{{ report.version??1 }} · 人工审查按版本保存</p><pre>{{ stringify(humanReview) }}</pre></details></div><template v-if="!readonly"><div class="workspace-actions"><button class="secondary-button" :disabled="!!busy||dirty" @click="action('validate')">检查当前版本</button><button class="secondary-button" :disabled="!!busy||dirty" @click="action('review')">AI 审查当前版本</button></div><details><summary>提交人工审查</summary><div class="field-grid"><label>审查人<input v-model="reviewer" aria-label="审查人" maxlength="100"/></label><label>结论<select v-model="decision" aria-label="人工审查结论"><option value="approved">通过</option><option value="needs_changes">需要修改</option></select></label><label class="full-width">说明<textarea v-model="reviewNotes" aria-label="人工审查说明" rows="3"/></label></div><button class="secondary-button" :disabled="!!busy||dirty||!reviewer.trim()" @click="action('human-review')">保存人工审查</button></details>
    <details><summary>编辑报告，保存为新版本</summary><div class="field-grid"><label class="full-width">报告标题<input v-model="draft.title" aria-label="编辑报告标题"/></label><label class="full-width">摘要<textarea v-model="draft.summary" aria-label="编辑报告摘要" rows="3"/></label><div v-for="(chapter,index) in draft.chapters" :key="chapter.id" class="full-width chapter-editor"><label>章节 {{ index+1 }}<input v-model="chapter.title" :aria-label="`编辑章节标题 ${index+1}`"/></label><label>正文<textarea :value="chapter.paragraphs.join('\n\n')" :aria-label="`编辑章节正文 ${index+1}`" rows="5" @input="chapter.paragraphs=($event.target as HTMLTextAreaElement).value.split(/\n\s*\n/).filter(Boolean)"/></label></div></div><details @toggle="($event.target as HTMLDetailsElement).open&&(jsonEditor=JSON.stringify(draft.workflow,null,2))"><summary>高级：编辑图解与结构 JSON</summary><textarea v-model="jsonEditor" aria-label="工作流结构 JSON" class="json-editor" rows="12"/><button class="secondary-button" @click="applyJson">应用结构到草稿</button></details><div class="workspace-actions"><button class="primary-button" :disabled="!!busy||!dirty" @click="save">保存新版本</button><button class="text-button" :disabled="!!busy" @click="run('reload',async()=>emit('saved',await getReport(report.id)))">载入服务端最新版（放弃本地编辑）</button></div></details>
    <h3>固定版本与历史</h3><div class="workspace-actions"><select v-model.number="selectedVersion" aria-label="历史版本"><option v-if="!versions.length" :value="report.version??1">v{{ report.version??1 }}</option><option v-for="version in versions" :key="version.version" :value="version.version">v{{ version.version }} · {{ version.title }}</option></select><button class="secondary-button" :disabled="!!busy" @click="loadPrevious">与当前版本比较</button><button class="secondary-button" :disabled="!!busy||selectedVersion===(report.version??1)||dirty" @click="restore">恢复为新版本</button></div><div v-if="previous" class="evidence-card"><strong>v{{ selectedVersion }} → v{{ report.version??1 }}</strong><p v-for="change in changes" :key="change">{{ change }}</p><p v-if="!changes.length">标题、摘要、章节及图解结构一致。</p><details><summary>查看所选版本正文</summary><div v-for="chapter in previous.chapters" :key="chapter.id"><h4>{{ chapter.title }}</h4><p v-for="(text,index) in chapter.paragraphs" :key="index">{{ text }}</p></div></details></div>
    <div class="workspace-actions"><button class="secondary-button" :disabled="!!busy" @click="download('zip')">下载自包含 ZIP</button><button class="secondary-button" :disabled="!!busy" @click="download('html')">下载固定版本 HTML</button><button class="primary-button" :disabled="!!busy||dirty" @click="publish">创建冻结版本分享</button></div><p class="muted">导出和分享均使用所选的已保存版本；分享链接有效期 24 小时，持有链接的人可阅读。</p><div v-if="shareUrl" class="share-result"><label>分享链接<input :value="shareUrl" readonly aria-label="分享链接" @focus="($event.target as HTMLInputElement).select()"/></label><a :href="shareUrl" target="_blank" rel="noopener" class="text-link">打开冻结报告</a><p>到期：{{ shareExpiry||'24 小时后' }}</p><button class="text-button" :disabled="!!busy" @click="revoke">撤销此分享链接</button></div><details><summary>撤销已有分享</summary><label>分享令牌<input v-model="shareToken" aria-label="待撤销分享令牌" placeholder="粘贴分享 URL 最后的令牌"/></label><button class="secondary-button" :disabled="!!busy||!shareToken" @click="revoke">撤销分享</button></details></template><details><summary>固定资产清单</summary><pre>{{ stringify(workflow.manifest) }}</pre></details></section>
  </details>
</template>
